<script setup lang="ts">defineProps<{items:{id:string;name:string;hypothesis:string;state:string;primary_metric:string;minimum_sample:number}[]}>();const emit=defineEmits<{submit:[value:{key:string;name:string;hypothesis:string;primaryMetric:string;minimumSample:number}]}>();const open=ref(false),form=reactive({key:"search.result-order.v2",name:"ترتیب نتایج جست‌وجو",hypothesis:"ترتیب جدید نتایج نرخ مشاهده آگهی را بدون افزایش گزارش تخلف بهتر می‌کند.",primaryMetric:"detail_view_rate",minimumSample:20000});</script><template><section class="analytics-panel experiment-workspace"><header><div><h2>آزمایش‌های کنترل‌شده</h2><p>تخصیص پایدار، Exposure یکتا و توقف خودکار Guardrail</p></div><button class="button button-secondary" type="button" @click="open=!open">آزمایش جدید</button></header><form v-if="open" class="experiment-form" @submit.prevent="emit('submit',{...form});open=false"><label>کلید<input v-model="form.key" required pattern="[a-z][a-z0-9_.-]{2,79}"></label><label>عنوان<input v-model="form.name" required minlength="3"></label><label class="wide">فرضیه<textarea v-model="form.hypothesis" required minlength="20"></textarea></label><label>شاخص اصلی<input v-model="form.primaryMetric" required></label><label>حداقل نمونه<input v-model.number="form.minimumSample" type="number" min="100" required></label><button class="button button-primary" type="submit">ثبت پیش‌نویس</button></form><article v-for="item in items" :key="item.id" class="experiment-card"><div><span :data-state="item.state">{{item.state==='running'?'در حال اجرا':'پیش‌نویس'}}</span><b>{{item.name}}</b><p>{{item.hypothesis}}</p></div><dl><div><dt>شاخص</dt><dd>{{item.primary_metric}}</dd></div><div><dt>حداقل نمونه</dt><dd>{{item.minimum_sample.toLocaleString('fa-IR')}}</dd></div><div><dt>Guardrail</dt><dd>سالم</dd></div></dl></article></section></template>
